// =====================================================================
// EVERWAKE CLINIC — Main · NODE: Normalize Inbound
// Evolution API payload -> one flat, predictable shape (the Everwake Orders
// contract), plus what a multi-clinic engine needs:
//   · instance + token   → which clinic, and proof it is Evolution
//   · phone and lid      → both identities, so a customer hidden behind a
//                          WhatsApp private id is still recognised
//   · from_me            → a message the clinic typed on the phone
//                          itself: logged for the inbox and the agent
// Captions count as text; a voice note / photo / sticker with no text
// goes through as a bracketed marker so the agent can answer naturally;
// a photo, a voice note or a PDF (a lab report) is understood first (Prepare Media).
// Reactions, edits, deletes and receipts are ignored.
// A run from the Test Runner workflow (test_run, next to the payload —
// a real webhook can't set it) is a pretend chat: Main records the
// replies but sends nothing on WhatsApp.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
// an Egyptian number as people write it: 201001234567 → 01001234567
const localPhone = (p) => str(p).replace(/^\+?20(1\d{9})$/, '0$1');
const payload = $input.first().json;
const makeRunId = () => ['run', Date.now(), Math.random().toString(36).slice(2, 10)].join('_');

const body = payload.body && typeof payload.body === 'object' ? payload.body : payload;
const query = obj(payload.query);
const data = body.data || payload.data || body;
const key = data.key || {};
const message = data.message || {};
const event = String(body.event || payload.event || '').toLowerCase();
const instance = str(body.instance || body.instanceName || data.instance || data.instanceName || payload.instance);
const token = str(query.token || query.t || '');
const testRun = payload.test_run === true;

// the team answered a question the agent asked (the dashboard): no patient message — the agent
// wakes up to pass the answer on. The channel's token proves it; intake checks there is a new answer.
if (event === 'clinic.team_answer' || event === 'everwake.team_answer') {
  const wa = String(data.wa_id || '').replace(/\D/g, '');
  const pretend = /^20000000000[0-9]$|^2000000000[1-9][0-9]$/.test(wa);   // a Test Runner chat: nothing goes out
  return [{
    json: {
      run_id: makeRunId(), instance, wa_id: wa, reply_to: wa, customer_message: '', message_type: 'team_answer',
      from_me: false, is_group: false, has_location: false, location: null, is_test: pretend, team_answer: true,
      is_ignorable: !wa || !instance, received_at: new Date().toISOString(),
      b64_intake: b64({ provider: 'evolution', instance, token, kind: 'team_answer', wa_id: wa, test_run: pretend || undefined })
    }
  }];
}

const text =
  message.conversation ||
  message.extendedTextMessage?.text ||
  message.imageMessage?.caption ||
  message.videoMessage?.caption ||
  message.documentMessage?.caption ||
  message.buttonsResponseMessage?.selectedDisplayText ||
  message.listResponseMessage?.title ||
  message.templateButtonReplyMessage?.selectedDisplayText ||
  data.messageText || data.text || '';

// a swipe-reply: WhatsApp attaches the message it answers (its id, and a copy of it)
const replyInfo = obj(Object.values(message).map(v => (v && typeof v === 'object' ? v.contextInfo : null)).find(c => c && (c.stanzaId || c.quotedMessage))
  || data.contextInfo);
const qm = obj(replyInfo.quotedMessage);
const quotedText = str(qm.conversation || obj(qm.extendedTextMessage).text || obj(qm.imageMessage).caption || obj(qm.videoMessage).caption
  || obj(qm.documentMessage).caption);
const quotedKind = qm.imageMessage ? 'photo' : qm.documentMessage ? 'file' : (qm.audioMessage || qm.pttMessage) ? 'voice note'
  : qm.locationMessage ? 'location pin' : qm.stickerMessage ? 'sticker' : (quotedText ? 'text' : '');
const quoted = (replyInfo.stanzaId || quotedKind) ? { id: str(replyInfo.stanzaId) || null, text: quotedText.slice(0, 400), kind: quotedKind } : null;

const location = message.locationMessage || message.liveLocationMessage || data.locationMessage || data.location || null;

const IGNORE = ['reactionMessage', 'protocolMessage', 'editedMessage', 'senderKeyDistributionMessage', 'pollUpdateMessage',
                'messageContextInfo'];
const msgType = data.messageType || Object.keys(message).filter(k => k !== 'messageContextInfo')[0] || 'text';
const isMessageEvent = !event || /messages[._]upsert/.test(event) || /send[._]message/.test(event);
const ignorable = IGNORE.includes(msgType) || !isMessageEvent;

const MEDIA_MARK = {
  audioMessage: '[voice note]', pttMessage: '[voice note]', imageMessage: '[photo]', videoMessage: '[video]',
  stickerMessage: '[sticker]', documentMessage: '[file]', contactMessage: '[contact card]'
};

const fromMe = Boolean(key.fromMe || data.fromMe || payload.fromMe) || /send[._]message/.test(event);
const remoteJid = String(key.remoteJid || data.remoteJid || data.from || payload.from || '');
const pushName = fromMe ? null : (data.pushName || payload.pushName || null);
const isGroup = remoteJid.includes('@g.us') || remoteJid.includes('@broadcast') || remoteJid.includes('@newsletter');

// WhatsApp often hides the phone behind a private id ("…@lid"); Evolution
// may give the real number in another field. reply_to = where a reply must
// go (the number, or the FULL "…@lid" jid); wa_id = the customer key.
const digitsOf = (j) => String(j || '').replace(/@.*$/, '').replace(/:\d+$/, '').replace(/\D/g, '');
const candidates = [key.remoteJid, key.remoteJidAlt, key.senderPn, data.senderPn, key.participantAlt, data.remoteJid, data.sender]
  .filter(Boolean).map(String);
const phoneJid = candidates.find(j => /@(s\.whatsapp\.net|c\.us)$/.test(j)) || null;
const lidJid = candidates.find(j => /@lid$/.test(j)) || null;
const phone = phoneJid ? digitsOf(phoneJid) : '';
const lid = lidJid ? digitsOf(lidJid) : '';
const waId = phone || lid || digitsOf(remoteJid);
const replyTo = phone || lidJid || digitsOf(remoteJid);
const phoneHidden = !phone && !!lid;
const messageId = key.id || data.id || data.messageId || payload.id || `${waId}_${Date.now()}`;

const lat = location?.degreesLatitude ?? location?.latitude ?? location?.lat ?? null;
const lng = location?.degreesLongitude ?? location?.longitude ?? location?.lng ?? null;
const hasLocation = lat !== null && lng !== null && Number.isFinite(Number(lat)) && Number.isFinite(Number(lng));

// a photo, a voice note or a PDF / image file: fetched and understood before the agent answers (Prepare Media)
const doc = message.documentMessage || message.documentWithCaptionMessage?.message?.documentMessage || null;
const docOk = doc && /^(application\/pdf|image\/)/.test(str(doc.mimetype));
const mediaMsg = message.audioMessage || message.pttMessage || message.imageMessage || (docOk ? doc : null) || null;
const media = mediaMsg && !fromMe ? {
  kind: message.imageMessage ? 'image' : (docOk && mediaMsg === doc ? (/^image\//.test(str(doc.mimetype)) ? 'image' : 'document') : 'audio'),
  mime: str(mediaMsg.mimetype) || (message.imageMessage ? 'image/jpeg' : 'audio/ogg'),
  seconds: Number(mediaMsg.seconds) || null,
  file_name: doc ? str(doc.fileName || doc.title) || null : null
} : null;
// Evolution can put the file in the webhook itself ("base64" on): then nothing needs fetching
const mediaB64 = media ? str(message.base64 || data.base64 || '') : '';

let customerMessage = String(text || '').trim();
if (!customerMessage && hasLocation) customerMessage = '[shared a location pin]';
if (!customerMessage && MEDIA_MARK[msgType]) customerMessage = MEDIA_MARK[msgType];

const locationObj = hasLocation ? {
  lat: Number(lat), lng: Number(lng),
  name: location?.name || null, address: location?.address || null,
  maps_url: `https://www.google.com/maps?q=${Number(lat)},${Number(lng)}`
} : null;

// keep the raw payload for support, minus media bytes and thumbnails
const slim = (v, depth = 0) => {
  if (depth > 6) return null;
  if (typeof v === 'string') return v.length > 2000 ? `[${v.length} chars]` : v;
  if (Array.isArray(v)) return v.slice(0, 20).map(x => slim(x, depth + 1));
  if (v && typeof v === 'object') {
    const o = {};
    for (const [k, x] of Object.entries(v)) {
      if (/^(base64|jpegThumbnail|thumbnail|mediaKey|fileEncSha256|fileSha256)$/i.test(k)) continue;
      o[k] = slim(x, depth + 1);
    }
    return o;
  }
  return v;
};

const intake = {
  provider: 'evolution', instance, token, external_id: messageId, wa_id: waId, reply_to: replyTo, phone, lid,
  phone_hidden: phoneHidden, push_name: pushName, text: customerMessage, message_type: hasLocation ? 'location' : msgType,
  media: media ? { kind: media.kind, file_name: media.file_name || undefined } : undefined,
  has_location: hasLocation, location: locationObj, from_me: fromMe, test_run: testRun || undefined, quoted: quoted || undefined,
  raw: slim({ event, instance, data: { key, pushName: data.pushName, messageType: data.messageType,
                                       messageTimestamp: data.messageTimestamp, message } })
};

return [{
  json: {
    run_id: makeRunId(),
    instance,
    wa_id: waId,
    reply_to: replyTo,
    phone_hidden: phoneHidden,
    customer_name: pushName,
    customer_message: customerMessage,
    external_id: messageId,
    message_type: intake.message_type,
    from_me: fromMe,
    is_group: isGroup,
    has_location: hasLocation,
    location: locationObj,
    is_test: testRun,
    media,
    media_b64: mediaB64 || undefined,
    is_ignorable: ignorable || !customerMessage || isGroup || !waId || !instance,
    received_at: new Date().toISOString(),
    b64_intake: b64(intake)
  }
}];

// =====================================================================
// EVERWAKE CLINIC — Main · NODE: Prepare Apology
// The agent is switched OFF. The first message from each patient during
// the pause gets one warm apology (the clinic's own wording, from
// Settings → Messages); everyone who wrote hears "we're back" later.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
// an Egyptian number as people write it: 201001234567 → 01001234567
const localPhone = (p) => str(p).replace(/^\+?20(1\d{9})$/, '0$1');
const r = row($input.first().json);
const norm = $('Normalize Inbound').first().json;
const ch = obj(r.channel);
const text = str(r.apology_text);
if (!text) return [];
return [{
  json: {
    tenant_id: r.tenant_id, wa_id: r.wa_id, reply_to: str(r.reply_to) || norm.wa_id, text, run_id: norm.run_id,
    base_url: str(ch.base_url), instance: str(ch.instance), api_key: str(ch.api_key)
  }
}];

// =====================================================================
// EVERWAKE CLINIC — Main · NODE: Record Apology
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
// an Egyptian number as people write it: 201001234567 → 01001234567
const localPhone = (p) => str(p).replace(/^\+?20(1\d{9})$/, '0$1');
const item = $('Prepare Apology').first().json;
const r = $input.first().json || {};
const body = obj(r.body && typeof r.body === 'object' ? r.body : r);
const id = str(obj(body.key).id) || null;
const ok = !!id && !r.error;
return [{
  json: {
    b64_log: b64({
      tenant_id: item.tenant_id, wa_id: item.wa_id, run_id: item.run_id, sender: 'system', kind: 'text',
      body: item.text, external_id: id, ok,
      error: ok ? null : str(obj(r.error).message || r.error || 'WhatsApp did not confirm the message').slice(0, 300),
      meta: { purpose: 'pause_notice' }
    })
  }
}];

// =====================================================================
// EVERWAKE CLINIC — Main · NODE: Prepare Media
// A patient's photo, voice note or PDF, ready for the model that
// understands it: the file (from the webhook itself, or fetched from
// Evolution), the transcription request for a voice note, the vision
// request for a photo or a PDF (a lab report, a prescription, an X-ray
// report). What it says or shows replaces "[voice note]" / "[photo]" /
// "[file]" for the agent (Media Understood); a photo or a file is also
// kept on the patient's record for the doctor (Save Document).
// The model only DESCRIBES and COPIES — it never interprets a result.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
// an Egyptian number as people write it: 201001234567 → 01001234567
const localPhone = (p) => str(p).replace(/^\+?20(1\d{9})$/, '0$1');
const norm = $('Normalize Inbound').first().json;
const intake = $('Intake').first().json.r;
const fetched = obj(obj($input.first().json).body);
const media = obj(norm.media);
const file64 = str(norm.media_b64) || str(fetched.base64);
const mime = (str(fetched.mimetype) || str(media.mime) || (media.kind === 'audio' ? 'audio/ogg' : 'image/jpeg')).split(';')[0].trim();
const ext = { 'audio/ogg': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp4': 'm4a', 'audio/aac': 'm4a', 'audio/amr': 'amr', 'audio/webm': 'webm',
              'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'application/pdf': 'pdf' }[mime] || (media.kind === 'audio' ? 'ogg' : 'jpg');
const marker = str(norm.customer_message);
const caption = /^\[(photo|voice note|file)\]$/.test(marker) ? '' : marker;

const VISION = `A patient (or a parent) sent this to a medical clinic on WhatsApp. Start with ONE tag in square brackets saying what it is — [lab] a lab or test result · [prescription] a prescription or a medicine box · [imaging] an X-ray, scan or its report · [photo] a photo of the body (skin, a wound, teeth, an eye, a swelling) · [report] a medical report or a referral · [card] an insurance card or an ID · [payment] a payment screenshot · [other] anything else. Then, in one to four short English sentences, what matters for the clinic:
- a lab or test result: each test name with its value and unit exactly as printed, which are marked high or low, the lab and the date;
- a prescription or medicine: the medicine names, strengths and directions exactly as written;
- an X-ray, scan or report: what kind it is, the body part, and any written findings or impression copied exactly — never read the image yourself;
- a photo of the body: plainly where it is and what is visible (size, colour, swelling) — never name a condition;
- an insurance card, an ID or a referral: the names, numbers and company as written;
- a payment screenshot: the amount, the reference, the date;
- anything else: what it is.
Copy written text exactly and never guess text you cannot read. Describe only — no diagnosis, no advice, no reply to the patient.`;

const isDoc = media.kind === 'document' || mime === 'application/pdf';
const kind = media.kind === 'audio' ? 'audio' : (isDoc ? 'document' : 'image');
const fileName = str(media.file_name) || `${kind === 'audio' ? 'voice' : kind === 'document' ? 'file' : 'photo'}.${ext}`;

return [{
  json: {
    kind,
    ok: file64.length > 100,
    b64: file64,
    mime,
    file_name: fileName,
    seconds: media.seconds || null,
    marker,
    caption,
    buffer_id: intake.buffer_id,
    message_id: intake.message_id,
    tenant_id: intake.tenant_id,
    wa_id: intake.wa_id,
    transcribe_model: 'gpt-transcribe',
    transcribe_prompt: 'A WhatsApp voice note to a medical clinic in Egypt, usually in Egyptian Arabic: booking a visit, days and times, symptoms, children\'s names and ages, medicine names, prices.',
    vision_model: 'gpt-5-mini',
    vision_body: kind !== 'audio' && file64 ? {
      model: 'gpt-5-mini',
      messages: [
        { role: 'system', content: VISION },
        { role: 'user', content: [
          { type: 'text', text: caption ? `They wrote with it: "${caption}"` : 'They sent it without text.' },
          kind === 'document'
            ? { type: 'file', file: { filename: fileName, file_data: `data:${mime};base64,${file64}` } }
            : { type: 'image_url', image_url: { url: `data:${mime};base64,${file64}` } }
        ] }
      ],
      max_completion_tokens: 2500,
      ...('low' ? { reasoning_effort: 'low' } : {})
    } : null
  }
}];

// =====================================================================
// EVERWAKE CLINIC — Main · NODE: Media Understood
// What the voice note said, or the photo / file showed, in the words the
// agent reads with the message: [voice note: «…»] · [photo: …] · [file: …]
// (their caption stays with it). A photo or a file is also kept on the
// patient's record (Save Document), tagged lab / prescription / imaging…
// A file that could not be fetched or understood says so plainly.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
// an Egyptian number as people write it: 201001234567 → 01001234567
const localPhone = (p) => str(p).replace(/^\+?20(1\d{9})$/, '0$1');
const prep = $('Prepare Media').first().json;
const r = obj($input.first().json);
let text, docKind = null, summary = '';
if (prep.kind === 'audio') {
  const heard = prep.ok ? str(r.text).trim() : '';
  text = heard ? `[voice note${prep.seconds ? ` (${prep.seconds}s)` : ''}: «${heard.slice(0, 2000)}»]` : '[voice note — it could not be played]';
} else {
  let seen = prep.ok ? str(obj(obj(arr(r.choices)[0]).message).content).replace(/\s+/g, ' ').trim() : '';
  const tag = seen.match(/^\[(lab|prescription|imaging|photo|report|card|payment|other)\]\s*/i);
  docKind = tag ? tag[1].toLowerCase() : (prep.kind === 'document' ? 'report' : 'photo');
  if (tag) seen = seen.slice(tag[0].length);
  summary = seen;
  const label = prep.kind === 'document' ? 'file' : 'photo';
  text = (seen ? `[${label} (${docKind}): ${seen.slice(0, 1500)}]` : `[${label} — it could not be opened]`) + (prep.caption ? ' ' + prep.caption : '');
}
const keep = prep.kind !== 'audio' && prep.ok && !!summary;
const kindForRecord = { lab: 'lab', prescription: 'prescription', imaging: 'imaging', photo: 'photo', report: 'report', card: 'other',
                        payment: 'other', other: 'other' }[docKind] || 'other';

return [{
  json: {
    understood: text,
    failed: !prep.ok || !!r.error,
    error: r.error ? str(obj(r.error).message || r.error).slice(0, 300) : null,
    b64_media: b64({ buffer_id: prep.buffer_id, message_id: prep.message_id, marker: prep.marker, text,
                     model: prep.kind === 'audio' ? prep.transcribe_model : prep.vision_model }),
    // kept on the record for the doctor (an empty string → Save Document does nothing)
    b64_doc: keep ? b64({ tenant_id: prep.tenant_id, wa_id: prep.wa_id, message_id: prep.message_id, kind: kindForRecord,
                          title: prep.file_name, summary: summary.slice(0, 4000), mime: prep.mime }) : ''
  }
}];

// =====================================================================
// EVERWAKE CLINIC — Main · NODE: Build Brief
// The clinic's rows → FACTS (only what is true right now), CLINIC (the
// catalogue snapshot: doctors, schedules, places, services and prices,
// offers, answers, the doctors' rules), the chat, the latest message.
// Two things are worked out in code, never by the model:
//   · the dates and times they mentioned (shared/dates.js)
//   · red flags (shared/triage.js) — an emergency is acted on whatever
//     the model makes of it (Persist raises the alert; Check Reply
//     makes sure the reply leads with the emergency guidance)
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
// an Egyptian number as people write it: 201001234567 → 01001234567
const localPhone = (p) => str(p).replace(/^\+?20(1\d{9})$/, '0$1');
// ---- shared: Arabic-aware matching (same rules as clinic.norm in SQL) --
function normalizeArabic(s) {
  return String(s == null ? '' : s).toLowerCase()
    .replace(/[ً-ٰٟـ]/g, '')
